@Override public void handle(RoutingContext context){
  if (ignoreContext(context)) {
    context.next();
    return;
  }
  try {
    executor.execute(createBlockingHandler(context));
  } catch (RuntimeException | ClassCastException | RejectedExecutionException | NullPointerException e) {
    // 处理异常，例如记录日志或返回错误响应
    context.fail(e);
  }
}
